public class FieldLevelEncryptionConfigFactory(string resourceName = null, Action<Humidifier.CloudFront.FieldLevelEncryptionConfig> factoryAction = null) : ResourceFactory<Humidifier.CloudFront.FieldLevelEncryptionConfig>(resourceName)
{

    internal InnerFieldLevelEncryptionConfigContentTypeProfileConfigFactory ContentTypeProfileConfigFactory { get; set; }

    internal InnerFieldLevelEncryptionConfigQueryArgProfileConfigFactory QueryArgProfileConfigFactory { get; set; }

    protected override Humidifier.CloudFront.FieldLevelEncryptionConfig Create()
    {
        var fieldLevelEncryptionConfigResult = CreateFieldLevelEncryptionConfig();
        factoryAction?.Invoke(fieldLevelEncryptionConfigResult);

        return fieldLevelEncryptionConfigResult;
    }

    private Humidifier.CloudFront.FieldLevelEncryptionConfig CreateFieldLevelEncryptionConfig()
    {
        var fieldLevelEncryptionConfigResult = new Humidifier.CloudFront.FieldLevelEncryptionConfig
        {
            GivenName = InputResourceName,
        };

        return fieldLevelEncryptionConfigResult;
    }
    public override void CreateChildren(Humidifier.CloudFront.FieldLevelEncryptionConfig result)
    {
        base.CreateChildren(result);

        result.ContentTypeProfileConfig ??= ContentTypeProfileConfigFactory?.Build();
        result.QueryArgProfileConfig ??= QueryArgProfileConfigFactory?.Build();
    }

} // End Of Class

